{
  "headline": "FDA's records trace our supply to a plant classified OAI 58 days after the shortage posting",
  "headline_cites": ["D16"],
  "sentences": [
    {
      "text": "FDA first posted the morphine sulfate injection shortage on 2017-10-31 and it remains current as of 2026-10-21.",
      "cites": ["E45", "D17"]
    },
    {
      "text": "The shortage listing names Fresenius Kabi USA, LLC as a company with current shortage status.",
      "cites": ["E39"]
    },
    {
      "text": "FDA's OAI classification letter to Fresenius Kabi USA, LLC is dated 2017-12-28, 58 days after FDA posted the shortage on 2017-10-31.",
      "cites": ["D16"]
    },
    {
      "text": "Inspection 732653 at the Fresenius Kabi plant ended 2011-07-08 and was classified OAI with the classification known on 2017-12-28.",
      "cites": ["E21"]
    },
    {
      "text": "Hikma Pharmaceuticals USA Inc. also appears on the FDA shortage list with current status and its registered plant last inspected 2026-05-13 with NAI classification.",
      "cites": ["E40", "E18"]
    },
    {
      "text": "Corvale East has 2.7 days of 2 mg/mL injection on hand while Corvale General has 16.7 days and can spare 51 units while keeping two weeks supply.",
      "cites": ["D1", "D2", "D18"]
    },
    {
      "text": "The recommended action is to transfer 51 units of 2 mg/mL, 1 mL from Corvale General to Corvale East, which requires pharmacy director approval plus a DEA Form 222 or CSOS order for this Schedule II substance.",
      "cites": ["D18"]
    }
  ]
}
